(function(root){function selectCommunes(features,origin,target,turf){const unique=new Map(features.map(f=>[f.properties.code,f]));const ranked=[...unique.values()].filter(f=>Number.isFinite(f.properties.population)&&f.properties.population>0).map(f=>{f._comparisonPoint??=turf.pointOnFeature(f);return {feature:f,distance:turf.booleanPointInPolygon(turf.point(origin),f)?0:turf.distance(turf.point(origin),f._comparisonPoint)};}).sort((a,b)=>a.distance-b.distance||a.feature.properties.code.localeCompare(b.feature.properties.code));let remaining=target;const selected=[];for(const {feature} of ranked){if(remaining<=0)break;const population=feature.properties.population,represented=Math.min(remaining,population);selected.push({feature,population,represented,fraction:represented/population});remaining-=represented;}return {selected,remaining,total:selected.reduce((s,row)=>s+row.population,0),missing:[...unique.values()].filter(f=>!Number.isFinite(f.properties.population)).length};}root.GazaSelection={selectCommunes};})(typeof window==='undefined'?globalThis:window);
